INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001030061','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001030061","revision":1,"targetId":"80000000-0000-4000-8000-000000010306","prompt":"Die Reparatur dauert länger; bitte haben Sie noch etwas ___.","instruction":{"en":"Choose the noun or noun form that best completes the German sentence.","de":"Wähle das Nomen oder die Nomenform, die den deutschen Satz sinnvoll ergänzt."},"hint":{"en":"The person is asked to wait calmly.","de":"Die Person soll noch ruhig warten."},"options":[{"id":"0","text":"Gegend"},{"id":"1","text":"Gehaltsabrechnung"},{"id":"2","text":"Geheimnis"},{"id":"3","text":"Geduld"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"3"}],"explanation":{"en":"Geduld means patience here; \"Geduld\" is the appropriate form.","de":"Geduld bedeutet hier: Geduld beim Warten. Die Form „Geduld“ passt in diesen Satz."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Reparatur dauert länger; bitte haben Sie noch etwas Geduld.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on pinned lexical and grammar facts from apps/web/data/pos/nouns.jsonl:L919 (3707635abbd28c2fa624531952d7ec461937f614408def31c112b3195e2a5b40), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
